import{_ as s,o as i,c as a,af as n}from"./chunks/framework.DyU3Y-qS.js";const d=JSON.parse('{"title":"Installing a Premium Plugin","description":"Installation instructions for premium plugins in Ts.ED.","frontmatter":{"description":"Installation instructions for premium plugins in Ts.ED.","head":[["meta",{"name":"description","content":"Installation instructions for premium plugins in Ts.ED. Learn how to install and configure private packages from GitHub."}],["meta",{"name":"keywords","content":"Ts.ED create plugins marketplace premium guide installation"}],["link",{"rel":"canonical","href":"https://tsed.dev/plugins/premium/install-premium-plugins.html"}]]},"headers":[],"relativePath":"plugins/premium/install-premium-plugins.md","filePath":"plugins/premium/install-premium-plugins.md","lastUpdated":1788975525000}'),t={name:"plugins/premium/install-premium-plugins.md"};function r(o,e,l,p,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /plugins/premium/install-premium-plugins.md for this page in Markdown format</div><h1 id="installing-a-premium-plugin" tabindex="-1">Installing a Premium Plugin <a class="header-anchor" href="#installing-a-premium-plugin" aria-label="Permalink to &quot;Installing a Premium Plugin&quot;">​</a></h1><p>Premium (private) Ts.ED plugins are distributed as private packages via GitHub&#39;s npm registry. To access and install them, you must:</p><ol><li><strong>Become a sponsor of Ts.ED at the required tier</strong></li><li><strong>Generate a GitHub Personal Access Token (PAT) with the correct permissions</strong></li><li><strong>Configure your project to use the token when installing packages</strong></li></ol><h2 id="_1-become-a-ts-ed-sponsor" tabindex="-1">1. Become a Ts.ED Sponsor <a class="header-anchor" href="#_1-become-a-ts-ed-sponsor" aria-label="Permalink to &quot;1. Become a Ts.ED Sponsor&quot;">​</a></h2><p>To access premium plugins, you must be an active sponsor at least at the <a href="https://github.com/sponsors/Romakita/sponsorships?tier_id=489429&amp;preview=false" target="_blank" rel="noreferrer">Power Dev tier</a>.</p><ul><li>For higher tiers and benefits, visit the <a href="https://github.com/romakita/sponsors" target="_blank" rel="noreferrer">Ts.ED sponsorship page</a>.</li><li>After subscribing, you&#39;ll receive a confirmation email with a link to access the private packages.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>You must be a sponsor to access Ts.ED&#39;s private packages.</strong></p></div><h2 id="_2-generate-a-github-personal-access-token" tabindex="-1">2. Generate a GitHub Personal Access Token <a class="header-anchor" href="#_2-generate-a-github-personal-access-token" aria-label="Permalink to &quot;2. Generate a GitHub Personal Access Token&quot;">​</a></h2><p>You need a GitHub Personal Access Token (PAT) with the <code>read:packages</code> scope. Here&#39;s how to create one:</p><ol><li>Go to your <strong>GitHub Account Settings</strong>.</li><li>Navigate to <strong>Developer settings</strong> &gt; <strong>Personal access tokens</strong> &gt; <strong>Tokens (classic)</strong>.</li><li>Click <strong>Generate new token</strong>.</li><li>Select the <strong><code>read:packages</code></strong> scope (you can uncheck other scopes for security).</li><li>Click <strong>Generate token</strong> and copy the resulting token.<br><em><strong>Keep your token secret!</strong></em></li></ol><h2 id="_3-configure-your-project" tabindex="-1">3. Configure Your Project <a class="header-anchor" href="#_3-configure-your-project" aria-label="Permalink to &quot;3. Configure Your Project&quot;">​</a></h2><p>You must configure your package manager to use your token for the <code>@tsedio</code> scope.<br><strong>Replace <code>GH_TOKEN</code> below with your actual token or use an environment variable such as <code>\${GH_TOKEN}</code>.</strong></p><h3 id="using-npm-or-pnpm" tabindex="-1">Using npm or pnpm <a class="header-anchor" href="#using-npm-or-pnpm" aria-label="Permalink to &quot;Using npm or pnpm&quot;">​</a></h3><p>Create or update a <code>.npmrc</code> file <strong>at the root of your project</strong> (or in your user home directory for global use):</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@tsedio:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">registry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://npm.pkg.github.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">//npm.pkg.github.com/:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">_authToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=GH_TOKEN</span></span></code></pre></div><ul><li>For <strong>pnpm</strong>, this configuration is also valid.</li></ul><h3 id="using-yarn-v1" tabindex="-1">Using Yarn v1 <a class="header-anchor" href="#using-yarn-v1" aria-label="Permalink to &quot;Using Yarn v1&quot;">​</a></h3><p>Add or update a <code>.yarnrc</code> file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;@tsedio:registry&quot; &quot;https://npm.pkg.github.com&quot;</span></span></code></pre></div><h3 id="using-yarn-v2-berry" tabindex="-1">Using Yarn v2+ (Berry) <a class="header-anchor" href="#using-yarn-v2-berry" aria-label="Permalink to &quot;Using Yarn v2+ (Berry)&quot;">​</a></h3><p>Add or update a <code>.yarnrc.yml</code> file:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">npmScopes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tsedio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    npmRegistryServer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://npm.pkg.github.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    npmAlwaysAuth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h3 id="security-recommendations" tabindex="-1">Security Recommendations <a class="header-anchor" href="#security-recommendations" aria-label="Permalink to &quot;Security Recommendations&quot;">​</a></h3><ul><li>Never commit your personal access token to version control.</li><li>Prefer using environment variables (e.g., replace <code>GH_TOKEN</code> with <code>\${GH_TOKEN}</code>) and inject them as part of your CI/CD pipeline or local environment.</li></ul><h2 id="_4-install-the-premium-plugin" tabindex="-1">4. Install the Premium Plugin <a class="header-anchor" href="#_4-install-the-premium-plugin" aria-label="Permalink to &quot;4. Install the Premium Plugin&quot;">​</a></h2><p>Once configured, you can install premium Ts.ED plugins as usual:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsedio/your-premium-plugin</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsedio/your-premium-plugin</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tsedio/your-premium-plugin</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>401 Unauthorized or 403 Forbidden</strong>: Ensure your sponsorship is active, the PAT has the <code>read:packages</code> scope, and your <code>.npmrc</code> or <code>.yarnrc*</code> files are correctly set up.</li><li><strong>Still need help?</strong> Contact <a href="mailto:contact@tsed.dev" target="_blank" rel="noreferrer">support</a> with your GitHub username and details.</li></ul>`,30)])])}const g=s(t,[["render",r]]);export{d as __pageData,g as default};
